import { request } from 'node:http';
import { readFile, readdir, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { performance } from 'node:perf_hooks';
import assert from 'node:assert/strict';

const root = resolve(process.argv[2] ?? process.cwd());
const output = join(root, 'docs/evidence/security-maintenance');
const cadDist = join(root, 'artifacts/kineticad/dist/public');
const landingDist = join(root, 'artifacts/landing/dist/public');
const sha = (bytes) => createHash('sha256').update(bytes).digest('hex');
const noStore = 'no-cache, no-store, must-revalidate';
const results = [];
const observations = [];
const startedAt = new Date().toISOString();

async function http(port, path, options = {}) {
  const start = performance.now();
  return new Promise((resolveResponse, reject) => {
    const body = options.body === undefined ? undefined : Buffer.from(options.body);
    const req = request({ hostname: '127.0.0.1', port, path, method: options.method ?? 'GET',
      headers: { ...(body ? { 'Content-Length': body.length } : {}), ...options.headers } }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('error', reject);
      res.on('end', () => resolveResponse({ status: res.statusCode, headers: res.headers,
        body: Buffer.concat(chunks), durationMs: performance.now() - start }));
    });
    req.on('error', reject);
    req.setTimeout(10000, () => req.destroy(new Error('HTTP request timed out')));
    req.end(body);
  });
}

function responseRecord(response) {
  return { status: response.status, headers: response.headers, bytes: response.body.length,
    sha256: sha(response.body), durationMs: response.durationMs };
}

async function check(name, port, path, expected, options = {}) {
  const row = { name, request: { method: options.method ?? 'GET',
    address: '127.0.0.1', port, path, headers: options.headers ?? {},
    bodyBytes: options.body === undefined ? 0 : Buffer.byteLength(options.body) },
    expected: { ...expected, bytesFromFile: expected.file ? expected.file.replace(root + '/', '') : undefined } };
  delete row.expected.file;
  try {
    const response = await http(port, path, options);
    row.response = responseRecord(response);
    assert.equal(response.status, expected.status);
    if (expected.mime) assert.match(response.headers['content-type'] ?? '', new RegExp(expected.mime));
    if (expected.cache) assert.equal(response.headers['cache-control'], expected.cache);
    if (expected.file) {
      const bytes = await readFile(expected.file);
      row.expected.fileSha256 = sha(bytes);
      assert.deepEqual(response.body, bytes);
    }
    if (expected.body !== undefined) assert.equal(response.body.toString(), expected.body);
    if (expected.json) assert.deepEqual(JSON.parse(response.body.toString()), expected.json);
    if (expected.empty) assert.equal(response.body.length, 0);
    if (expected.noSourceDisclosure) {
      assert.doesNotMatch(response.body.toString(), /node_modules|SyntaxError|PayloadTooLargeError|\/Users\/|at (?:JSON|parse|read|Layer)\b/);
    }
    row.passed = true;
  } catch (error) {
    row.passed = false;
    row.error = String(error.message ?? error);
  }
  results.push(row);
}

const cadHtml = await readFile(join(cadDist, 'index.html'), 'utf8');
const landingHtml = await readFile(join(landingDist, 'index.html'), 'utf8');
const cadEntry = cadHtml.match(/src="([^"]+\.js)"/)?.[1];
const landingEntry = landingHtml.match(/src="([^"]+\.js)"/)?.[1];
assert.ok(cadEntry?.startsWith('/app/assets/'), 'CAD build uses /app base');
assert.ok(landingEntry?.startsWith('/assets/'), 'landing build uses / base');
const cadAssets = await readdir(join(cadDist, 'assets'));
const css = cadAssets.find((file) => file.endsWith('.css'));
const cadWorker = cadAssets.find((file) => file.startsWith('cadWorker-') && file.endsWith('.js'));
const physicsWorker = cadAssets.find((file) => file.startsWith('physicsWorker-') && file.endsWith('.js'));
assert.ok(css && cadWorker && physicsWorker, 'all actual built asset classes are present');

for (const path of ['/app', '/app/', '/app/simulator', '/app/simulator?from=smoke']) {
  await check(`CAD SPA ${path}`, 5192, path, { status: 200, mime: '^text/html', cache: noStore, file: join(cadDist, 'index.html') });
}
for (const path of [cadEntry, `/app/assets/${css}`, `/app/assets/${cadWorker}`, `/app/assets/${physicsWorker}`]) {
  await check(`CAD exact built asset ${path}`, 5192, path, { status: 200,
    mime: path.endsWith('.css') ? '^text/css' : 'javascript',
    cache: 'public, max-age=31536000, immutable', file: join(cadDist, path.replace('/app/', '')) });
}
await check('CAD existing demo JSON', 5192, '/app/demos/windmill.json', {
  status: 200, mime: '^application/json', cache: noStore, file: join(cadDist, 'demos/windmill.json'),
});
await check('CAD legacy seed script', 5192, '/app/seeds/windmill.js', {
  status: 200, mime: 'javascript', cache: noStore, file: join(cadDist, 'seeds/windmill.js'),
});
await check('CAD branded favicon', 5192, '/app/favicon.svg', {
  status: 200, mime: '^image/svg', cache: noStore, file: join(cadDist, 'favicon.svg'),
});
await check('CAD HEAD route', 5192, '/app/simulator', { status: 200, mime: '^text/html', cache: noStore, empty: true }, { method: 'HEAD' });
await check('CAD HEAD hashed asset', 5192, cadEntry, { status: 200, mime: 'javascript', cache: 'public, max-age=31536000, immutable', empty: true }, { method: 'HEAD' });
for (const path of ['/app/assets/nonexistent-security-smoke.js', '/app/assets/nonexistent-security-smoke.wasm', '/app/demos/nonexistent-security-smoke.json', `/application${cadEntry.slice(4)}`]) {
  await check(`CAD missing/base-boundary ${path}`, 5192, path, { status: 404, mime: '^text/plain', cache: noStore, body: 'Not found' });
}
await check('CAD HEAD missing asset', 5192, '/app/assets/nonexistent-security-smoke.js', { status: 404, cache: noStore, empty: true }, { method: 'HEAD' });
for (const path of ['//[', 'http://[']) {
  await check(`CAD malformed request target ${path}`, 5192, path, { status: 400, mime: '^text/plain', cache: noStore, body: 'Bad request' });
}
await check('CAD still serves after malformed targets', 5192, '/app/', { status: 200, file: join(cadDist, 'index.html'), cache: noStore });

for (const path of ['/', '/story', '/terms', '/privacy']) {
  await check(`Landing route ${path}`, 5193, path, { status: 200, mime: '^text/html', file: join(landingDist, 'index.html') });
}
await check('Landing exact root-base bundle', 5193, landingEntry, {
  status: 200, mime: 'javascript', file: join(landingDist, landingEntry),
});
await check('Landing HEAD root', 5193, '/', { status: 200, mime: '^text/html', empty: true }, { method: 'HEAD' });
await check('Landing preview rejects unrelated Host', 5193, '/', { status: 403 }, { headers: { Host: 'unrelated-security-smoke.invalid' } });
await check('Landing still serves after rejected Host', 5193, '/', { status: 200, file: join(landingDist, 'index.html') });
const landingMissing = await http(5193, '/assets/nonexistent-security-smoke.js');
observations.push({ name: 'Missing asset behavior of local Vite landing preview', request: '/assets/nonexistent-security-smoke.js',
  response: responseRecord(landingMissing), note: 'Observed only; actual Replit landing production uses its static hosting and rewrite configuration, not this Vite preview server.' });

await check('API production health JSON', 5194, '/api/healthz', { status: 200, mime: '^application/json', json: { status: 'ok' } });
await check('API HEAD health', 5194, '/api/healthz', { status: 200, mime: '^application/json', empty: true }, { method: 'HEAD' });
await check('API missing route', 5194, '/api/nonexistent-security-smoke', { status: 404, noSourceDisclosure: true });
await check('API malformed JSON receives safe 400', 5194, '/api/healthz', { status: 400, noSourceDisclosure: true }, {
  method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{"unfinished":',
});
await check('API default JSON size limit rejects oversize input', 5194, '/api/healthz', { status: 413, noSourceDisclosure: true }, {
  method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ value: 'x'.repeat(120 * 1024) }),
});
await check('API still serves after errors', 5194, '/api/healthz', { status: 200, mime: '^application/json', json: { status: 'ok' } });

const paths = ['pnpm-lock.yaml', 'pnpm-workspace.yaml', '.replit',
  'artifacts/kineticad/serve.mjs', 'artifacts/kineticad/vite.config.ts',
  'artifacts/landing/vite.config.ts', 'artifacts/api-server/src/app.ts',
  'artifacts/kineticad/.replit-artifact/artifact.toml', 'artifacts/landing/.replit-artifact/artifact.toml',
  'artifacts/api-server/.replit-artifact/artifact.toml',
  'artifacts/kineticad/dist/public/index.html', 'artifacts/landing/dist/public/index.html', 'artifacts/api-server/dist/index.mjs',
  'docs/evidence/security-maintenance/final-workspace-build.txt', 'docs/evidence/security-maintenance/final-landing-root-build.txt'];
const hashes = Object.fromEntries(await Promise.all(paths.map(async (path) => [path, sha(await readFile(join(root, path)))])));
const report = {
  schemaVersion: 1, startedAt, completedAt: new Date().toISOString(),
  passed: results.every((row) => row.passed), counts: { checks: results.length, passed: results.filter((row) => row.passed).length, failed: results.filter((row) => !row.passed).length },
  runtime: { node: process.version, architecture: process.arch, platform: process.platform, executable: process.execPath },
  gitHead: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
  provenance: { sourceAndBuildSha256: hashes, requestTransport: 'Actual Node HTTP client requests to listening services at127.0.0.1 only' },
  servers: [
    { name: 'CAD', url: 'http://localhost:5192/app/', sessionId: 66110, launch: 'PORT=5192 BASE_PATH=/app NODE_ENV=production node artifacts/kineticad/serve.mjs', productionEntrypoint: true },
    { name: 'Landing', url: 'http://localhost:5193/', sessionId: 33305, launch: 'PORT=5193 BASE_PATH=/ NODE_ENV=production pnpm --filter @workspace/landing serve', productionEntrypoint: false, note: 'Vite preview of final built bytes; Replit serves these files statically.' },
    { name: 'API', url: 'http://localhost:5194/api/healthz', sessionId: 66202, launch: 'PORT=5194 NODE_ENV=production node --enable-source-maps artifacts/api-server/dist/index.mjs', productionEntrypoint: true },
  ],
  checks: results, observations,
  limitations: [
    'HTTP/status/header/byte checks only. No browser rendering, actual Replit proxy/domain or deployment acceptance is claimed.',
    'These are smoke checks, not additional automated suite test cases or a penetration test.',
    'No external endpoint was requested. CDN-delivered OCCT WASM and browser worker startup remain separate browser checks.',
    'Malformed targets specifically exercise WHATWG URL parse failures; no broad parser/fuzzing claim.',
    'Local Vite preview is used only to inspect the final landing build; its host/fallback behavior is not an assertion about Replit static hosting.',
  ],
  reproduction: { runtime: 'Prepend the recorded Node24ARM64 executable directory to PATH, start the three services with the listed commands, save this script outside the repository and run node script.mjs <repository-root>.', script: await readFile(fileURLToPath(import.meta.url), 'utf8') },
};
await writeFile(join(output, 'http-smoke.json'), JSON.stringify(report, null, 2) + '\n');
const lines = [
  'KinetiCAD final security-maintenance HTTP smoke',
  `Started: ${report.startedAt}`, `Completed: ${report.completedAt}`,
  `Node: ${report.runtime.node} ${report.runtime.platform}/${report.runtime.architecture}`,
  `Result: ${report.counts.passed}/${report.counts.checks} checks passed; ${report.counts.failed} failed`,
  'Actual HTTP on127.0.0.1:5192(CAD),5193(landing preview),5194(API). Services left available for Chrome.',
  '', ...results.map((row) => `${row.passed ? 'PASS' : 'FAIL'} ${row.name}: ${row.response?.status ?? 'request error'}, ${row.response?.bytes ?? '?'} bytes, ${row.response?.headers?.['content-type'] ?? 'no MIME'}, SHA256 ${row.response?.sha256 ?? '-'}${row.error ? `; ${row.error}` : ''}`),
  '', ...observations.map((row) => `OBSERVATION ${row.name}: status${row.response.status}; ${row.note}`),
  '', ...report.limitations.map((line) => `LIMIT ${line}`),
  '', 'Full request/response headers, expected source-byte hashes, source/build fingerprints and portable reproduction script: http-smoke.json',
];
await writeFile(join(output, 'http-smoke.txt'), lines.join('\n') + '\n');
console.log(JSON.stringify({ passed: report.passed, counts: report.counts,
  failures: results.filter((row) => !row.passed).map((row) => ({ name: row.name, error: row.error })),
  landingMissingAssetStatus: landingMissing.status }, null, 2));
process.exitCode = report.passed ? 0 : 1;
